def text(b):
    return b.decode('utf-8', 'replace')
try:
    p = poplib.POP3('127.0.0.1', port, timeout=230)
    print('GREETING', text(p.getwelcome()))
    print('USER', text(p.user('eval')))
    print('PASS', text(p.pass_('eval-password')))
